$dir = "C:\Users\016551\OneDrive\Desktop\audit-temp\-dante-habits\skills\md-cleanup"
$files = Get-ChildItem $dir -Recurse -File | Where-Object { $_.Extension -match '\.(md|json|yaml|yml|py|txt)$' }
foreach ($f in $files) {
    $content = Get-Content $f.FullName -Raw -Encoding UTF8
    if ($content -match 'Openear') {
        $content = $content -replace 'Openear', 'Category'
        Set-Content -Path $f.FullName -Value $content -Encoding UTF8 -NoNewline
        Write-Host "Fixed: $($f.FullName)"
    }
}
